-- =============================================================================
-- FindMyPal - FOUND & REUNITED people
-- Snapshot exported from live SpacetimeDB via FastAPI /persons
-- Row count: 4
-- =============================================================================

CREATE TABLE IF NOT EXISTS persons_export (
    id                       TEXT PRIMARY KEY,
    name                     TEXT NOT NULL,
    age                      INTEGER,
    gender                   TEXT,
    last_seen_location       TEXT,
    last_seen_date           TEXT,
    description              TEXT,
    photo_url                TEXT,
    status                   TEXT,
    police_report_number     TEXT,
    created_at               TEXT,
    ai_summary               TEXT,
    ai_summary_updated_at    TEXT,
    verified_police_report   BOOLEAN,
    last_verified_at         TEXT,
    found_at                 TEXT,
    found_message            TEXT,
    watchers_count           INTEGER,
    shares_count             INTEGER,
    tips_count               INTEGER,
    suspicious_flags         INTEGER,
    under_review             BOOLEAN,
    owner_token              TEXT,
    contact_email            TEXT,
    last_seen_time           TEXT,
    source_listing_url       TEXT,
    source_agency_name       TEXT,
    external_case_number     TEXT,
    source_last_checked_at   TEXT,
    found_date               TEXT,
    found_notes              TEXT,
    verified_by              TEXT
);

